package com.airesumebuilder.feature.pdf.repository;
import com.airesumebuilder.common.exception.ResourceNotFoundException;import java.sql.*;import java.time.Instant;import java.util.List;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository public class PdfExportRepository{private final JdbcTemplate jdbc;public PdfExportRepository(JdbcTemplate j){jdbc=j;}public ResumeDocument resume(String email,long id){return jdbc.query("SELECT r.id,r.title,r.summary,r.target_job_title,CONCAT_WS(' ',u.first_name,u.last_name) full_name,u.id user_id FROM resumes r JOIN users u ON u.id=r.user_id WHERE u.email=? AND r.id=? AND r.deleted_at IS NULL",(r,n)->new ResumeDocument(r.getLong("id"),r.getLong("user_id"),r.getString("title"),r.getString("summary"),r.getString("target_job_title"),r.getString("full_name")),email,id).stream().findFirst().orElseThrow(()->new ResourceNotFoundException("Resume not found."));}public void record(ResumeDocument r,String name,long size,String hash){jdbc.update("INSERT INTO pdf_exports(user_id,resume_id,file_name,byte_size,content_sha256,created_at) VALUES (?,?,?,?,?,NOW(6))",r.userId(),r.id(),name,size,hash);}public List<Export>history(String email,long resumeId){return jdbc.query("SELECT p.id,p.resume_id,p.file_name,p.byte_size,p.content_sha256,p.created_at FROM pdf_exports p JOIN users u ON u.id=p.user_id WHERE u.email=? AND p.resume_id=? ORDER BY p.created_at DESC",this::map,email,resumeId);}private Export map(ResultSet r,int n)throws SQLException{return new Export(r.getLong("id"),r.getLong("resume_id"),r.getString("file_name"),r.getLong("byte_size"),r.getString("content_sha256"),r.getTimestamp("created_at").toInstant());}public record ResumeDocument(long id,long userId,String title,String summary,String targetJobTitle,String fullName){}public record Export(long id,long resumeId,String fileName,long byteSize,String sha256,Instant createdAt){} }
